const data = $input.first().json;
const productName = data.productName || 'Unknown Product';
const currentStock = data.currentStock || 0;
const minimumStock = data.minimumStock || 0;

const severity = currentStock === 0 ? 'CRITICAL' : 'WARNING';

const notification = {
  subject: `[${severity}] Low Stock Alert - ${productName}`,
  body: `LOW STOCK ALERT

Product: ${productName}
Current Stock: ${currentStock}
Minimum Stock: ${minimumStock}
Severity: ${severity}

Please restock this product as soon as possible.

---
UMKM MANAGEMENT Inventory System`,
  productName: productName,
  currentStock: currentStock,
  minimumStock: minimumStock,
  severity: severity,
  productId: data.productId
};

return [{ json: notification }];

const data = $input.first().json;
console.log('=== LOW STOCK ALERT ===');
console.log('Product:', data.productName);
console.log('Current Stock:', data.currentStock);
console.log('Minimum Stock:', data.minimumStock);
console.log('Severity:', data.severity);
console.log('=======================');

return [{ json: { ...data, sentAt: new Date().toISOString(), status: 'logged' } }];
